using System;namespace _3.B{class Program{static void Main(string[] args){Console.WriteLine("Skriv ett tal");int tal1 = int.Parse(Console.ReadLine());Console.WriteLine("Skriv in ett tal till");int tal2 = int.Parse(Console.ReadLine());if (tal1 > 10){if(tal2 > 10) Console.WriteLine("Båda är större än 10");else Console.WriteLine($"{tal1} är större än 10");}else if (tal2 > 10) Console.WriteLine($"{tal2} är större än 10");else Console.WriteLine("Inga är större än 10");}}}